INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 1, 'Exercises: sets');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 0, 'How many subsets does the empty set have?', '["1"]', 'Substitute zero elements into 2ⁿ.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 1, 'A set is written as a list: "two, one, one". How many elements does it have?', '["2"]', 'Repeats in a set collapse into one element.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 2, 'Set A has four elements, set B has six, and their intersection has one. How many elements are in the union of A and B?', '["9"]', 'The naive sum counts the common element twice — remove the one extra.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 3, 'An app has 10 followers, and 4 of them are already friends. How many followers are in the difference "followers minus friends"?', '["6"]', 'The difference is what is in the first set and absent from the second.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 4, 'It is known that it is not true that at least one of two conditions holds. Does this mean that neither of the conditions holds?', '["yes", "true"]', 'This is De Morgan''s law: negation flips "or" into "and".');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 5, 'How many subsets does a set of 5 elements have?', '["32"]', 'For each of the five elements you decide: take it or not. Two choices per element.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 1, 6, 'A programmer goes through all subsets of a 10-element set, skipping the empty set and the full set itself. How many options remain?', '["1022"]', 'There are 1024 subsets in total — from the chapter. Subtract the two excluded cases.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 2, 'Exercises: relations and functions');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 0, 'Three T-shirts and two pairs of trousers. How many outfits does the Cartesian product contain?', '["6"]', 'Each independent choice multiplies: 3 × 2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 1, 'One set has 5 elements, the second has 4. How many pairs are in their Cartesian product?', '["20"]', 'The number of pairs is the product of the cardinalities.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 2, 'Is the relation "less than" on numbers reflexive?', '["no", "false"]', 'Reflexivity means: every element is related to itself. A number is not less than itself.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 3, 'Is the relation "follows" in a social network symmetric?', '["no", "false"]', 'Symmetry: if the first is related to the second, then the second is related to the first. A blogger may not follow you.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 4, 'Is the relation "is an ancestor of" transitive?', '["yes", "true"]', 'Check the chain: is an ancestor of an ancestor also an ancestor?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 5, 'A function reads the current time and returns a result based on it. Is it pure?', '["no", "false"]', 'A pure function depends only on its arguments and does not look at the outside world.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 6, 'Can a function be an injection and a surjection at the same time?', '["yes", "true"]', 'Such a correspondence has its own name — and it is invertible.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 2, 7, '8 guests are seated on 10 chairs, each guest sitting on exactly one chair. Can the mapping "guest → chair" be a surjection?', '["no", "false"]', 'A surjection requires every chair to be occupied. Count the maximum number of occupied chairs.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 3, 'Exercises: combinatorics');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 0, 'How many different four-digit PIN codes are there, if any of the ten digits can be at each position?', '["10000"]', 'Ten options for each of the four positions — the product rule.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 1, 'What is 4! (factorial) equal to?', '["24"]', 'Multiply all the numbers from 1 to 4.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 2, 'By how many times does the space of passwords grow when a password is lengthened by one character, if the alphabet is 95 printable symbols?', '["95"]', 'Each new character multiplies the space by the size of the alphabet.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 3, 'A conference with 5 talks. In how many ways can the running order be arranged?', '["120"]', 'This is a permutation: 5!.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 4, '20 athletes compete for gold, silver and bronze. How many ways are there to distribute the awards?', '["6840"]', 'Order matters: 20 × 19 × 18.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 5, 'In how many ways can two reviewers be chosen from six in the pool, if order does not matter?', '["15"]', 'This is C(6,2): six for the first place, five for the second, and divide by the permutations of the pair.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 6, '10 people in a room shake hands with each other, everyone with everyone exactly once. How many handshakes are there?', '["45"]', 'The number of pairs without repeats: C(10,2) = 10 × 9 / 2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 3, 7, 'How many four-digit PIN codes are there without repeated digits?', '["5040"]', 'This is an arrangement: 10! / 6!, that is, 10 × 9 × 8 × 7.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 4, 'Exercises: binomial, Pascal and Dirichlet');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 0, 'The sum of all numbers in the row of Pascal''s triangle corresponding to a set of 6 elements equals 2⁶. What is that?', '["64"]', 'A power of two: six twos multiplied together.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 1, 'What coefficient stands at a²b² in the expansion of (a + b)⁴?', '["6"]', 'The binomial coefficients are a row of Pascal''s triangle "1, 4, 6, 4, 1". Or compute C(4,2).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 2, 'Using the symmetry of the row, find C(6,5).', '["6"]', 'Choosing the five to take is the same as choosing the one to leave: C(6,1).');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 3, 'Forty people started the audio course, 30 watched the webinar, and 10 people did both. How many people were reached by at least one of them?', '["60"]', 'Ten people were counted twice — subtract them once.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 4, 'A hash table has 10 cells. How many elements need to be inserted for a collision to become guaranteed?', '["11"]', 'There must become more rabbits than cages.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 5, 'How many candidate pairs for a birthday match are there in a group of 23 people? It is C(23,2).', '["253"]', '23 × 22, divided by two.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 4, 6, 'Out of 100 people, 55 know English, 45 German, 25 French; pairwise intersections: 18, 12 and 8; all three languages — 5. How many people know none of the three languages?', '["8"]', 'First inclusion–exclusion: the sum minus the pairwise plus the triple. Then subtract the result from 100.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 5, 'Exercises: propositional logic');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 0, 'How many rows are in the truth table of a formula of two variables?', '["4"]', 'Two variables, each with two values: 2².');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 1, 'How many rows are in the truth table of a formula of three variables?', '["8"]', '2³ — the same count as for the power set.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 2, 'Is the statement "if two is greater than three, then I am a ballerina" formally true?', '["yes", "true"]', 'The premise is false — and what happens to an implication with a false premise?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 3, 'Does the statement "all elements of the array satisfy the condition" return true on an empty array?', '["yes", "true"]', 'No elements — no violators.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 4, 'Is the mathematical "or" true when both of its parts are true?', '["yes", "true"]', 'The mathematical "or" is inclusive, not exclusive.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 5, 'In the expression "a and b" with short-circuiting, the left part a turned out to be false. Will the right part b be evaluated?', '["no", "false"]', '"And" already knows the outcome: a false left operand decides everything.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 6, 'How many rows are in the truth table of a formula of five variables?', '["32"]', '2⁵ — a full enumeration of all combinations of values.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 5, 7, 'A contradiction is the formula "rain and no rain at the same time". In how many rows of its truth table is it true?', '["0"]', 'A contradiction is false in all rows — count in how many it is true.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 6, 'Exercises: predicates and quantifiers');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 0, 'Is the predicate "age is greater than 18" true for the value 20?', '["yes", "true"]', 'Substitute the value into the predicate — you get an ordinary statement.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 1, 'The array [2, 4, 6]. Is the statement "every element of the array is even" true?', '["yes", "true"]', 'This is a universal quantifier over a finite set — check each element.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 2, 'The array [2, 4]. Is the statement "there is an odd element" true?', '["no", "false"]', 'An existential quantifier requires at least one suitable element.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 3, 'It is known that not all passengers are buckled up. Does it follow that there is an unbuckled passenger?', '["yes", "true"]', 'Negating a universal quantifier changes it into the opposite one.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 4, 'It is known that among the guests there is not a single vegetarian. Does it follow that every guest is a non-vegetarian?', '["yes", "true"]', 'Negating an existential quantifier changes it into a universal quantifier.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 5, 'The every method with predicate p returned false. Does this guarantee that some with the negated predicate returns true?', '["yes", "true"]', '"Not for all elements p is true" = "there is an element for which p is false".');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 6, 'Do the statements "for every request there is its own handler" and "there is one handler for all requests" mean the same thing?', '["no", "false"]', 'The order of quantifiers changes the meaning: in the second case one handler is chosen for everyone.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 6, 7, 'The array [1, 3, 5]. Is the statement "for every element of the array there is an element in it greater than it" true?', '["no", "false"]', 'Check the maximal element: is there a greater one for it?');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 7, 'Exercises: induction and recurrences');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 0, 'What is the sum of all the numbers from 1 to 4?', '["10"]', '1 + 2 + 3 + 4. Or the formula n(n+1)/2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 1, 'What is the sum of all the numbers from 1 to 100? As Gauss counted: 100 × 101 halved.', '["5050"]', 'Add 100 and 101, divide by two.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 2, 'Fibonacci numbers: F(1) = 1, F(2) = 1, each next one is the sum of the two previous. What is F(5)?', '["5"]', 'Write them out in order: 1, 1, and then sum the pairs.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 3, 'In strong induction the step may rely on all the previous values at once, not only on the neighboring one. Is this true?', '["yes", "true"]', 'The staircase of strong induction simply has more supporting steps.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 4, 'Merge sort splits an array of 8 elements in half down to pieces of one. How many levels of splitting are there?', '["3"]', '8 → 4 → 2 → 1. Count the arrows.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 5, 'Quicksort picks an extreme pivot each time: an array of 100 elements turns into 99, then into 98. How many levels of recursion are there in this worst case?', '["100"]', 'The array shrinks by exactly one element per level — from 100 to zero.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 6, 'A loop invariant must be true before each iteration and after each. Is this true?', '["yes", "true"]', 'Before the first turn — the base; preservation across a turn — the step.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 7, 7, 'Merge sort on an array of 8 elements: there are 3 levels of splitting, and at each level the total work over all the pieces is 8. How many units of work in total?', '["24"]', 'Multiply the work of one level by the number of levels: 8 × 3.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 8, 'Exercises: graphs');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 0, 'The sum of the degrees of all vertices of an undirected graph is 20. How many edges does it have?', '["10"]', 'The handshake lemma: the sum of degrees equals twice the number of edges.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 1, 'A directed graph has 7 arrows. What is the sum of the in-degrees of all vertices?', '["7"]', 'Each arrow enters exactly once.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 2, 'Can a graph have exactly one vertex of odd degree?', '["no", "false"]', 'The sum of degrees is always even — what follows for the number of odd terms?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 3, 'Package a requires b, b requires c, and c requires a. Does a correct installation order for these packages exist?', '["no", "false"]', 'A cycle in a dependency graph is a synonym for trouble.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 4, 'An undirected graph: 3 vertices connected pairwise (3 edges), no loops. How many ones are in its adjacency matrix?', '["6"]', 'Each edge gives two ones: at the intersection of the pair in both directions.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 5, 'Can the sum of the degrees of all vertices of an undirected graph equal 21?', '["no", "false"]', 'The sum of degrees is twice the number of edges. Can a doubled number be odd?');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 8, 6, 'An undirected graph has 4 vertices with degrees 1, 2, 3 and 4. How many edges does it have?', '["5"]', 'First add up the degrees, then remember the doubling.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 9, 'Exercises: traversals and trees');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 0, 'How many edges are in a tree with 10 vertices?', '["9"]', 'A tree has a formula: exactly n − 1 edges.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 1, 'Depth-first traversal is naturally held by a stack, and breadth-first traversal by a queue. Is this true?', '["yes", "true"]', 'Depth goes to the limit and steps back; breadth spreads like a wave in circles.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 2, 'Breadth-first traversal finds shortest paths in an unweighted graph. Is this true?', '["yes", "true"]', 'The wave first checks everyone at distance one, then at distance two.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 3, 'A graph of 5 vertices: there are edges 1–2 and 3–4, vertex 5 is not connected to anyone. How many connected components are there?', '["3"]', 'A component is an island of mutually reachable vertices. Count the islands: {1,2}, {3,4} and...');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 4, 'In the Königsberg problem there were 4 vertices of odd degree. Is it possible there to cross each bridge exactly once?', '["no", "false"]', 'An Eulerian path exists only with zero or two odd vertices.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 5, 'A connected graph with 7 vertices and 6 edges. Is it guaranteed to have no cycles?', '["yes", "true"]', 'Compare the number of edges with n − 1: if it matches for a connected graph, you are looking at a tree.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 9, 6, 'You need to link 20 servers with cables so that the network is connected and has no extra cycles (a spanning tree). What is the minimal number of channels required?', '["19"]', 'The skeleton of a network is a tree: exactly n − 1 edges.');
INSERT INTO answer_sets (book_id, chapter, title) VALUES (12, 10, 'Exercises: probability and Bayes');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 0, 'A die: what is the probability of rolling an even number?', '["0.5", "0,5", "1/2"]', 'Three of the six faces are favorable — divide.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 1, 'Five coins are tossed. How many outcomes does this experiment have in total?', '["32"]', 'Each coin doubles the options: 2⁵.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 2, 'A coin is tossed twice. What is the probability that tails comes up both times?', '["0.25", "0,25", "1/4"]', 'The tosses are independent: multiply 1/2 and 1/2.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 3, 'P(A) = 0.5, P(B) = 0.2, the probability of both at once is 0.1. What is the probability that A or B happens?', '["0.6", "0,6"]', 'The sum of the probabilities minus the probability of the intersection.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 4, 'The events "an even number came up" and "a three came up" are incompatible. Are they independent?', '["no", "false"]', 'Having learned about the three, you know for certain that it is not even. Dependence is about information.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 5, 'In a group of 23 people, is the probability that two share a birthday greater than 50 percent?', '["yes", "true"]', 'Intuition counts people, but you have to count pairs — there are almost two hundred and fifty.');
INSERT INTO answer_tasks (book_id, chapter, ord, q, answers, hint) VALUES (12, 10, 6, 'One person in 1000 has the disease. The test catches a sick person in 99 cases out of 100, but wrongly flags a healthy one in 1 case out of 100. The test is positive. Approximately what percent is the probability of the disease (round to a whole number)?', '["9"]', 'Per hundred thousand people: the test will catch about a hundred sick, but will also falsely flag about a thousand healthy. Compare these numbers.');
